def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    threshold = 50000

    qualifying_years = []
    if v1 < threshold:
        qualifying_years.append(2018)
    if v2 < threshold:
        qualifying_years.append(2019)

    return {
        "value": qualifying_years[0] if qualifying_years else None,
        "trace": {
            "threshold": threshold,
            "2018_expense": v1,
            "2019_expense": v2,
            "qualifying_years": qualifying_years,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
